  "common/timeline.js",
  "common/ui/dom.js",
  "common/ui/move-list.js",
  "common/ui/settings.js",
  "common/ui/setup.js",
  "games.js",
  "games/bivalent/game.js",
  "games/bivalent/index.html",
  "games/broadcast/game.js",
