// END FILES

const urlOf = (file) => new URL(file, location).href;

// Cache key for a request: directory URLs are their index.html; the query
// and fragment are dropped.
function keyOf(url) {
  const u = new URL(url);
  u.search = "";
  u.hash = "";
  if (u.pathname.endsWith("/")) u.pathname += "index.html";
  return u.href;
}

// Fetch every file again (revalidating the HTTP cache) and store what arrives.
async function cacheAll() {
  const cache = await caches.open(CACHE);
  const results = await Promise.allSettled(FILES.map(async (file) => {
    const res = await fetch(urlOf(file), { cache: "no-cache" });
    if (!res.ok) throw new Error(`${file}: ${res.status}`);
    await cache.put(urlOf(file), res);
  }));
  const failed = results.filter((r) => r.status === "rejected").length;
  return { total: FILES.length, cached: FILES.length - failed };
}

// Drop cached files the site no longer has (e.g. a removed game).
async function prune() {
  const keep = new Set(FILES.map(urlOf));
  const cache = await caches.open(CACHE);
  for (const req of await cache.keys()) if (!keep.has(req.url)) await cache.delete(req);
}

self.addEventListener("install", (event) => {
  event.waitUntil(cacheAll().then(() => self.skipWaiting()));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(prune().then(() => self.clients.claim()));
});

self.addEventListener("message", (event) => {
  if (event.data !== "refresh") return;
  event.waitUntil(cacheAll().then(async (status) => {
    await prune();
    event.source?.postMessage({ type: "offline-status", ...status });
  }));
});

async function respond(request) {
  const key = keyOf(request.url);
  const cache = await caches.open(CACHE);
  const cached = await cache.match(key);
  const network = fetch(request).then((res) => {
    if (res.ok && res.type === "basic") cache.put(key, res.clone());
    return res;
  });
  if (!cached) return network;
  const timeout = new Promise((resolve) => setTimeout(() => resolve(cached), TIMEOUT_MS));
  return Promise.race([network.catch(() => cached), timeout]);
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET" || new URL(request.url).origin !== location.origin) return;
  event.respondWith(respond(request));
});
